begin;
do $$
declare w uuid:=gen_random_uuid();other uuid:=gen_random_uuid();a uuid:=gen_random_uuid();t uuid:=gen_random_uuid();t2 uuid:=gen_random_uuid();sid uuid:=gen_random_uuid();dev uuid:=gen_random_uuid();lift uuid:=gen_random_uuid();bid uuid:=gen_random_uuid();oid uuid:=gen_random_uuid();task uuid:=gen_random_uuid();cid uuid:=gen_random_uuid();p jsonb;r jsonb;s jsonb;before_order jsonb;failed boolean;passed int:=0;rev bigint;td uuid:=gen_random_uuid();ts uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(a,'agenda-admin-'||a||'@example.invalid'),(t,'agenda-tech-'||t||'@example.invalid'),(t2,'agenda-tech2-'||t2||'@example.invalid');insert into auth.sessions(id,user_id) values(sid,a),(ts,t2);
 insert into private.workshops(id,name) values(w,'Fictional rolled-back agenda'),(other,'Fictional isolated agenda');insert into private.members values(w,a,'Fictional admin','admin',true,true),(w,t,'Fictional tech','technician',false,true),(w,t2,'Fictional tech 2','technician',false,true),(other,a,'Fictional admin','admin',true,true);
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sid)::text,true);perform public.device_snapshot(w,dev);
 r:=public.apply_operation(w,dev,jsonb_build_object('id',gen_random_uuid(),'orderId',oid,'actorId',a,'kind','receive','baseRevision',0,'at',now(),'payload',jsonb_build_object('plate','9182FIC','country','ES','vin','FICTIONAL-AGENDA','vehicle','Fictional','engine','2020','client','Fictional owner','phone','','km',100,'symptom','Fictional symptom','tasks',jsonb_build_array(jsonb_build_object('id',task,'title','Diagnosis','assignees',jsonb_build_array(t),'estimateMinutes',30)))));if r->>'status'<>'accepted' then raise exception 'Source fixture failed';end if;
 r:=public.planning_command(w,dev,gen_random_uuid(),'schedule_resource',jsonb_build_object('id',lift,'revision',0,'name','Fictional lift','active',true,'reason','Fictional lift'));if r->>'saved'<>'true' then raise exception 'Lift config';end if;passed:=passed+1;
 s:=public.device_snapshot(w,dev);before_order:=s->'orders'->0;
 p:=jsonb_build_object('id',bid,'revision',1,'title','Fictional appointment','start',now()+interval '1 day','end',now()+interval '1 day 1 hour','kind','appointment','assignees',jsonb_build_array(t,t2),'liftId',lift,'orderId',oid,'reason','Private office evidence');
 r:=public.planning_command(w,dev,cid,'schedule_booking',p);if r->>'saved'<>'true' then raise exception 'Reserve';end if;passed:=passed+1;
 if public.planning_command(w,dev,cid,'schedule_booking',p)<>r then raise exception 'Retry mismatch';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,dev,cid,'schedule_booking',p||'{"title":"Changed retry"}');exception when others then failed:=true;end;if not failed then raise exception 'Changed ID accepted';end if;passed:=passed+1;
 s:=public.device_snapshot(w,dev);if s->'orders'->0<>before_order then raise exception 'Reservation altered money or repair';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,dev,gen_random_uuid(),'schedule_booking',p||jsonb_build_object('id',gen_random_uuid()));exception when others then failed:=true;end;if not failed then raise exception 'Stale concurrent booking';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,dev,gen_random_uuid(),'schedule_booking',p||jsonb_build_object('id',gen_random_uuid(),'revision',2));exception when others then failed:=true;end;if not failed then raise exception 'Shared lift/technician overlap';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,dev,gen_random_uuid(),'schedule_booking',p||jsonb_build_object('id',gen_random_uuid(),'revision',2,'start','2026-02-30T09:00:00Z'));exception when others then failed:=true;end;if not failed then raise exception 'Normalized invalid date';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,dev,gen_random_uuid(),'schedule_resource',jsonb_build_object('id',lift,'revision',2,'name','Fictional lift','active',false,'reason','Fictional retirement'));exception when others then failed:=true;end;if not failed then raise exception 'Lift retired with future reservations';end if;passed:=passed+1;
 r:=public.planning_command(w,dev,gen_random_uuid(),'schedule_booking',p||jsonb_build_object('revision',2,'start',now()+interval '2 days','end',now()+interval '2 days 1 hour'));s:=public.device_snapshot(w,dev);if jsonb_array_length(s->'planning'->'bookings'->0->'versions')<>2 or s->'planning'->'bookings'->0->'versions'->0->>'kind'<>'appointment' then raise exception 'Original version missing';end if;passed:=passed+1;
 perform public.planning_command(w,dev,gen_random_uuid(),'schedule_status',jsonb_build_object('id',bid,'revision',3,'status','cancelled','reason','Fictional cancellation'));s:=public.device_snapshot(w,dev);if jsonb_array_length(s->'planning'->'bookings'->0->'events')<>3 then raise exception 'History erased';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,dev,gen_random_uuid(),'schedule_booking',p||jsonb_build_object('revision',4));exception when others then failed:=true;end;if not failed then raise exception 'Finished booking overwritten';end if;passed:=passed+1;
 r:=public.planning_command(w,dev,gen_random_uuid(),'schedule_booking',p||jsonb_build_object('id',gen_random_uuid(),'revision',4,'kind','unavailable','orderId',null));passed:=passed+1;
 perform set_config('request.jwt.claim.sub',t2::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',t2,'session_id',ts)::text,true);s:=public.device_snapshot(w,td);
 if jsonb_array_length(s->'planning'->'bookings'->0->'events')<>0 or s->'planning'->'bookings'->0->>'orderId' is not null or (s->'planning')::text like '%Private office evidence%' then raise exception 'Private evidence leaked to technician';end if;passed:=passed+1;
 failed:=false;begin perform public.planning_command(w,td,gen_random_uuid(),'schedule_booking',p);exception when others then failed:=true;end;if not failed then raise exception 'Technician wrote agenda';end if;passed:=passed+1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'session_id',sid)::text,true);
 s:=public.workshop_snapshot(other);if jsonb_array_length(s->'planning'->'bookings')<>0 then raise exception 'Cross-workshop read';end if;passed:=passed+1;
 if has_table_privilege('authenticated','private.planning_state','select') or has_function_privilege('anon','public.planning_command(uuid,uuid,uuid,text,jsonb)','execute') then raise exception 'Direct access';end if;passed:=passed+1;
 r:=public.export_workshop(w,dev);if r->>'databaseVersion'<>'12' or jsonb_array_length(r->'tables'->'planning_state')<>1 then raise exception 'Archive missing';end if;perform private.validate_planning(w,r->'tables'->'planning_state'->0->'data');passed:=passed+1;
 perform set_config('tallerflow.planning_checks',passed::text,true);
end $$;
select current_setting('tallerflow.planning_checks')::int as checks_passed,'Hosted PostgreSQL; synthetic Auth; full rollback' as scope;
rollback;
